problems = [{'id': 'DRAGON-86', 'title': 'Chia Băng Số (Đoạn Bằng Nhau)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào 1 băng số có $n$ phần tử nguyên dương $a_1, a_2, \\dots, a_n$. Hãy chia băng số này thành nhiều đoạn con liên tiếp nhất sao cho tổng các phần tử trong mỗi đoạn bằng nhau. In ra số đoạn nhiều nhất có thể chia được.', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 1000$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số đoạn nhiều nhất có thể chia được.', 'constraints': '$1 \\le n \\le 1000$\\n$1 \\le a_i \\le 1000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '8\n10 2 6 2 5 2 1 2', 'sample_output': '3', 'hints': 'Tổng mảng là $S$. Thử số đoạn $k$ từ $n$ giảm dần về 1. Nếu $S \\% k == 0$, kiểm tra xem có thể cộng dồn tạo thành $k$ đoạn tổng $S/k$ không.', 'python_starter': "# Bí kíp luyện rồng - Chia Băng Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Chia Băng Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    total = sum(nums)\n    for k in range(n, 1, -1):\n        if total % k == 0:\n            target = total // k\n            cur = 0\n            possible = True\n            for x in nums:\n                cur += x\n                if cur == target:\n                    cur = 0\n                elif cur > target:\n                    possible = False\n                    break\n            if possible and cur == 0:\n                print(k)\n                return\n    print(1)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        long long a[1005];\n        long long total = 0;\n        for (int i = 0; i < n; i++) {\n            scanf("%lld", &a[i]);\n            total += a[i];\n        }\n        for (int k = n; k >= 2; k--) {\n            if (total % k == 0) {\n                long long target = total / k;\n                long long cur = 0;\n                bool ok = true;\n                for (int i = 0; i < n; i++) {\n                    cur += a[i];\n                    if (cur == target) {\n                        cur = 0;\n                    } else if (cur > target) {\n                        ok = false;\n                        break;\n                    }\n                }\n                if (ok && cur == 0) {\n                    printf("%d\\n", k);\n                    return 0;\n                }\n            }\n        }\n        printf("1\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Giả sử ta chia mảng thành $k$ đoạn có tổng bằng nhau thì tổng toàn mảng $S$ phải chia hết cho $k$, và tổng mỗi đoạn là $T = S / k$. Vì cần tìm $k$ lớn nhất, ta thử $k$ giảm dần từ $n$ về 1. Với mỗi $k$, ta duyệt mảng và cộng dồn các phần tử; khi tổng đạt đúng $T$ ta bắt đầu đoạn mới. Nếu gặp tổng con vượt quá $T$ thì cách chia không hợp lệ.\\n- **Độ phức tạp:** Thời gian $O(n \\cdot d(S))$ với $d(S)$ là số ước số của $S$, Bộ nhớ $O(n)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 1: 3 đoạn tổng 10)', 'input_data': '8\n10 2 6 2 5 2 1 2\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Không thể chia (Mẫu 2: 1 đoạn)', 'input_data': '5\n1 2 3 4 5\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Mọi phần tử bằng nhau (chia k = n)', 'input_data': '4\n5 5 5 5\n', 'expected_output': '4\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Chia làm 2 nửa đối xứng', 'input_data': '6\n1 2 3 3 2 1\n', 'expected_output': '2\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Mảng toàn số 2', 'input_data': '6\n2 2 2 2 2 2\n', 'expected_output': '6\n'}]}, {'id': 'DRAGON-87', 'title': 'Xâu Fibonacci', 'chapter': 'Phần VI. Dãy số & Đệ quy cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': "Nhập vào 1 số nguyên dương $n$. In ra xâu Fibonacci thứ $n$.\\nĐịnh nghĩa xâu Fibonacci:\\n- $f(1) = \\text{'A'}$\\n- $f(2) = \\text{'B'}$\\n- $f(i) = f(i-1) + f(i-2)$ với mọi $i \\ge 3$ (phép $+$ là phép ghép hai xâu).", 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 20$).', 'output_format': 'In ra xâu Fibonacci thứ $n$.', 'constraints': '$1 \\le n \\le 20$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '3', 'sample_output': 'BA', 'hints': 'Với $n \\le 20$, độ dài xâu Fibonacci tối đa chỉ vài nghìn ký tự. Ta có thể nối chuỗi trực tiếp từ $f(1)$ và $f(2)$.', 'python_starter': "# Bí kíp luyện rồng - Xâu Fibonacci\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Xâu Fibonacci\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n == 1:\n        print("A")\n        return\n    if n == 2:\n        print("B")\n        return\n    f1 = "A"\n    f2 = "B"\n    for _ in range(3, n + 1):\n        f_next = f2 + f1\n        f1 = f2\n        f2 = f_next\n    print(f2)\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n == 1) {\n            printf("A\\n");\n            return 0;\n        }\n        if (n == 2) {\n            printf("B\\n");\n            return 0;\n        }\n        char *f1 = (char*)malloc(1000000);\n        char *f2 = (char*)malloc(1000000);\n        char *f3 = (char*)malloc(1000000);\n        strcpy(f1, "A");\n        strcpy(f2, "B");\n        for (int i = 3; i <= n; i++) {\n            strcpy(f3, f2);\n            strcat(f3, f1);\n            strcpy(f1, f2);\n            strcpy(f2, f3);\n        }\n        printf("%s\\n", f2);\n        free(f1); free(f2); free(f3);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Bắt đầu với $f(1) = \\text{"A"}$ và $f(2) = \\text{"B"}$. Ở mỗi bước thứ $i \\ge 3$, xâu mới được tạo bằng cách nối $f(i-1)$ với $f(i-2)$ (chú ý thứ tự là $f(i-1) + f(i-2)$). Với $n \\le 20$, xâu $f(20)$ có độ dài $6765$ ký tự, hoàn toàn vừa trong bộ nhớ và chạy tức thời.\\n- **Độ phức tạp:** Thời gian $O(\\text{len}(f(n)))$, Bộ nhớ $O(\\text{len}(f(n)))$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 1 n = 3)', 'input_data': '3\n', 'expected_output': 'BA\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test mẫu 2 (n = 6)', 'input_data': '6\n', 'expected_output': 'BABBABAB\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Biên dưới (n = 1)', 'input_data': '1\n', 'expected_output': 'A\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Biên dưới (n = 2)', 'input_data': '2\n', 'expected_output': 'B\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Xâu n = 7', 'input_data': '7\n', 'expected_output': 'BABBABABBABBA\n'}]}, {'id': 'DRAGON-88', 'title': 'Đoạn Con Bằng Nhau Dài Nhất', 'chapter': 'Phần IV. Mảng một chiều', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 88 trong Bí kíp luyện rồng:\n\nNhập vào mảng $A$ gồm $n$ phần tử. Hãy tìm đoạn con liên tiếp dài nhất chứa các phần tử bằng nhau.\n\nIn ra số lượng phần tử của đoạn con tìm được.', 'input_format': 'Dòng 1 ghi số nguyên dương $n$ ($1 \\le n \\le 1000$). Dòng 2 ghi $n$ số nguyên $a_i$ ($-10^6 \\le a_i \\le 10^6$).', 'output_format': 'In ra 1 số nguyên duy nhất là độ dài đoạn con dài nhất.', 'constraints': '$1 \\le n \\le 1000$; $-10^6 \\le a_i \\le 10^6$.', 'sample_input': '8\n1 2 2 2 3 4 3 4', 'sample_output': '3', 'hints': 'Duyệt qua mảng, duy trì một biến `cur_len` đếm số phần tử liên tiếp giống nhau. Nếu $a_i == a_{i-1}$ thì `cur_len++`, ngược lại reset `cur_len = 1`.', 'python_starter': "# Bí kíp luyện rồng - Bài 88: Đoạn Con #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 88: Đoạn Con #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    input_data = sys.stdin.read().split()\n    if not input_data:\n        return\n    n = int(input_data[0])\n    a = [int(x) for x in input_data[1:n+1]]\n    if not a:\n        print(0)\n        return\n    max_len = 1\n    cur_len = 1\n    for i in range(1, len(a)):\n        if a[i] == a[i-1]:\n            cur_len += 1\n            if cur_len > max_len:\n                max_len = cur_len\n        else:\n            cur_len = 1\n    print(max_len)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n <= 0) { printf("0\\n"); return 0; }\n        long long prev, curr;\n        scanf("%lld", &prev);\n        int max_len = 1, cur_len = 1;\n        for (int i = 1; i < n; i++) {\n            scanf("%lld", &curr);\n            if (curr == prev) {\n                cur_len++;\n                if (cur_len > max_len) max_len = cur_len;\n            } else {\n                cur_len = 1;\n            }\n            prev = curr;\n        }\n        printf("%d\\n", max_len);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Sử dụng kỹ thuật duyệt tuyến tính (Linear scan):\n  - Khởi tạo `max_len = 1`, `cur_len = 1`.\n  - Duyệt $i$ từ 1 đến $n-1$: nếu $a[i] == a[i-1]$ thì `cur_len++` và cập nhật `max_len = max(max_len, cur_len)`. Nếu khác nhau, đặt lại `cur_len = 1`.\n- Độ phức tạp thời gian: $O(N)$, bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu sách: 1 2 2 2 3 4 3 4 -> 3)', 'input_data': '8\n1 2 2 2 3 4 3 4\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Tất cả khác nhau -> 1)', 'input_data': '5\n1 2 3 4 5\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (Mảng 1 phần tử)', 'input_data': '1\n100\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test tất cả phần tử bằng nhau', 'input_data': '6\n7 7 7 7 7 7\n', 'expected_output': '6\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test mảng lớn 1000 phần tử', 'input_data': '10\n-5 -5 -5 -5 2 2 2 2 2 -5\n', 'expected_output': '5\n'}]}, {'id': 'DRAGON-89', 'title': 'Đoạn Con #2 (Phần Tử Dương Dài Nhất)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào mảng $A$ gồm $n$ phần tử. Tìm độ dài của đoạn con liên tiếp dài nhất chỉ chứa các phần tử dương ($a_i > 0$).', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên $a_i$ ($-10^6 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số lượng phần tử của đoạn con tìm được.', 'constraints': '$1 \\le n \\le 1000$\\n$-10^6 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '8\n1 2 2 -2 3 -4 3 3', 'sample_output': '3', 'hints': 'Duyệt qua mảng: nếu phần tử $> 0$, tăng biến đếm đoạn hiện tại; ngược lại reset về 0. Luôn cập nhật độ dài lớn nhất.', 'python_starter': "# Bí kíp luyện rồng - Đoạn Con #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đoạn Con #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    max_len = 0\n    cur_len = 0\n    for x in nums:\n        if x > 0:\n            cur_len += 1\n            if cur_len > max_len:\n                max_len = cur_len\n        else:\n            cur_len = 0\n    print(max_len)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int max_len = 0, cur_len = 0;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                if (x > 0) {\n                    cur_len++;\n                    if (cur_len > max_len) max_len = cur_len;\n                } else {\n                    cur_len = 0;\n                }\n            }\n        }\n        printf("%d\\n", max_len);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Duyệt tuyến tính qua mảng với biến đếm `cur_len`. Nếu gặp số dương ($x > 0$), tăng `cur_len` và cập nhật `max_len = max(max_len, cur_len)`. Nếu gặp số không dương ($x \\le 0$), đặt lại `cur_len = 0`.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '8\n1 2 2 -2 3 -4 3 3\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Toàn bộ là số âm', 'input_data': '5\n-1 -2 -3 -4 -5\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Toàn bộ là số dương', 'input_data': '5\n1 2 3 4 5\n', 'expected_output': '5\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Có số 0 ngắt đoạn', 'input_data': '6\n2 0 3 4 5 0\n', 'expected_output': '3\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Đoạn dương ở giữa mảng', 'input_data': '10\n1 2 -1 3 4 5 6 -2 7 8\n', 'expected_output': '4\n'}]}, {'id': 'DRAGON-90', 'title': 'Đoạn Con #3 (Đơn Điệu Dài Nhất)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào mảng $A$ gồm $n$ phần tử. Tìm độ dài đoạn con liên tiếp dài nhất chứa các phần tử tăng dần hoặc giảm dần (tăng nghiêm ngặt hoặc giảm nghiêm ngặt: $a_i < a_{i+1}$ hoặc $a_i > a_{i+1}$).', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên $a_i$ ($-10^6 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra độ dài lớn nhất của đoạn con tìm được.', 'constraints': '$1 \\le n \\le 1000$\\n$-10^6 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '8\n1 2 2 -2 -2 2 3 5', 'sample_output': '4', 'hints': 'Duy trì hai biến độ dài: `inc` (đang tăng) và `dec` (đang giảm). Cập nhật `max_len = max(max_len, inc, dec)` tại mỗi bước.', 'python_starter': "# Bí kíp luyện rồng - Đoạn Con #3\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đoạn Con #3\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    if n <= 1:\n        print(n)\n        return\n    max_len = 1\n    inc = 1\n    dec = 1\n    for i in range(1, n):\n        if nums[i] > nums[i - 1]:\n            inc += 1\n            dec = 1\n        elif nums[i] < nums[i - 1]:\n            dec += 1\n            inc = 1\n        else:\n            inc = 1\n            dec = 1\n        if inc > max_len:\n            max_len = inc\n        if dec > max_len:\n            max_len = dec\n    print(max_len)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n <= 1) {\n            printf("%d\\n", n);\n            return 0;\n        }\n        long long a[1005];\n        for (int i = 0; i < n; i++) {\n            scanf("%lld", &a[i]);\n        }\n        int max_len = 1, inc = 1, dec = 1;\n        for (int i = 1; i < n; i++) {\n            if (a[i] > a[i - 1]) {\n                inc++;\n                dec = 1;\n            } else if (a[i] < a[i - 1]) {\n                dec++;\n                inc = 1;\n            } else {\n                inc = 1;\n                dec = 1;\n            }\n            if (inc > max_len) max_len = inc;\n            if (dec > max_len) max_len = dec;\n        }\n        printf("%d\\n", max_len);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Đoạn con đơn điệu nghiêm ngặt liên tiếp có thể là tăng dần ($a_i < a_{i+1}$) hoặc giảm dần ($a_i > a_{i+1}$). Ta duyệt mảng từ vị trí thứ hai: nếu $a_i > a_{i-1}$, tăng chuỗi tăng `inc += 1` và reset chuỗi giảm `dec = 1`; nếu $a_i < a_{i-1}$, tăng chuỗi giảm `dec += 1` và reset `inc = 1`; nếu bằng nhau thì cả hai chuỗi đều reset về 1.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(n)$ hoặc $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '8\n1 2 2 -2 -2 2 3 5\n', 'expected_output': '4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Mảng giảm nghiêm ngặt', 'input_data': '5\n5 4 3 2 1\n', 'expected_output': '5\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Tất cả các số bằng nhau', 'input_data': '4\n2 2 2 2\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Mảng chỉ 1 phần tử', 'input_data': '1\n42\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Đoạn giảm dài ở đuôi', 'input_data': '7\n1 3 5 2 1 0 -1\n', 'expected_output': '5\n'}]}, {'id': 'DRAGON-91', 'title': 'Đoạn Con #4 (Âm Dương Đan Xen)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào mảng $A$ gồm $n$ số nguyên khác 0. Tìm độ dài của đoạn con liên tiếp dài nhất chứa các phần tử âm dương đan xen nhau (hai phần tử liền kề trái dấu: $a_i \\times a_{i+1} < 0$).', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên khác 0 của mảng $A$ ($-10^6 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số lượng phần tử của đoạn con tìm được.', 'constraints': '$1 \\le n \\le 1000$\\n$-10^6 \\le a_i \\le 10^6, a_i \\ne 0$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '8\n1 2 2 -2 3 -4 3 3', 'sample_output': '5', 'hints': 'Kiểm tra hai phần tử liền kề có trái dấu không bằng điều kiện $(a_i > 0 \\land a_{i-1} < 0) \\lor (a_i < 0 \\land a_{i-1} > 0)$.', 'python_starter': "# Bí kíp luyện rồng - Đoạn Con #4\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đoạn Con #4\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    if n == 0:\n        print(0)\n        return\n    max_len = 1\n    cur = 1\n    for i in range(1, n):\n        if (nums[i] > 0 and nums[i - 1] < 0) or (nums[i] < 0 and nums[i - 1] > 0):\n            cur += 1\n        else:\n            cur = 1\n        if cur > max_len:\n            max_len = cur\n    print(max_len)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n == 0) {\n            printf("0\\n");\n            return 0;\n        }\n        long long a[1005];\n        for (int i = 0; i < n; i++) scanf("%lld", &a[i]);\n        int max_len = 1, cur = 1;\n        for (int i = 1; i < n; i++) {\n            if ((a[i] > 0 && a[i - 1] < 0) || (a[i] < 0 && a[i - 1] > 0)) {\n                cur++;\n            } else {\n                cur = 1;\n            }\n            if (cur > max_len) max_len = cur;\n        }\n        printf("%d\\n", max_len);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Duyệt tuần tự qua mảng $A$. So sánh phần tử hiện tại $a_i$ với phần tử đứng trước $a_{i-1}$. Nếu hai phần tử trái dấu (một dương, một âm), đoạn con đan xen kéo dài thêm 1 đơn vị. Ngược lại nếu cùng dấu, đoạn con đan xen bắt đầu lại từ $a_i$ với độ dài 1.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 1)', 'input_data': '8\n1 2 2 -2 3 -4 3 3\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test mẫu 2', 'input_data': '8\n-1 -2 1 -3 -1 4 -5 5\n', 'expected_output': '4\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Toàn bộ cùng dấu dương', 'input_data': '4\n1 2 3 4\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Đan xen hoàn hảo từ đầu đến cuối', 'input_data': '5\n1 -1 1 -1 1\n', 'expected_output': '5\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Mảng 1 phần tử', 'input_data': '1\n-7\n', 'expected_output': '1\n'}]}, {'id': 'DRAGON-92', 'title': 'Đoạn Con #5 (Chia Hết Cho K)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào mảng $A$ gồm $n$ phần tử và số nguyên dương $k$. Tìm độ dài của đoạn con liên tiếp dài nhất chứa các phần tử chia hết cho $k$ ($a_i \\% k == 0$).', 'input_format': 'Dòng 1: Hai số nguyên dương $n$ và $k$ ($1 \\le n \\le 1000, 1 \\le k \\le 1000$).\\nDòng 2: $n$ số nguyên $a_i$ ($-10^6 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra độ dài lớn nhất của đoạn con tìm được (in 0 nếu không có phần tử nào chia hết cho $k$).', 'constraints': '$1 \\le n \\le 1000$\\n$1 \\le k \\le 1000$\\n$-10^6 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '8 2\n1 2 2 -2 6 -4 3 3', 'sample_output': '5', 'hints': 'Duyệt qua mảng: nếu $a_i \\% k == 0$, tăng biến đếm đoạn hiện tại; ngược lại reset về 0.', 'python_starter': "# Bí kíp luyện rồng - Đoạn Con #5\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đoạn Con #5\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n, k = int(tokens[0]), int(tokens[1])\n    nums = [int(x) for x in tokens[2:n+2]]\n    max_len = 0\n    cur = 0\n    for x in nums:\n        if x % k == 0:\n            cur += 1\n            if cur > max_len:\n                max_len = cur\n        else:\n            cur = 0\n    print(max_len)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n, k;\n    if (scanf("%d %d", &n, &k) == 2) {\n        int max_len = 0, cur = 0;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                if (x % k == 0) {\n                    cur++;\n                    if (cur > max_len) max_len = cur;\n                } else {\n                    cur = 0;\n                }\n            }\n        }\n        printf("%d\\n", max_len);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Duyệt mảng tuần tự. Mỗi khi gặp phần tử chia hết cho $k$ ($x \\% k == 0$), tăng độ dài chuỗi liên tiếp `cur` và cập nhật `max_len`. Nếu không chia hết, đặt `cur = 0`.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 1)', 'input_data': '8 2\n1 2 2 -2 6 -4 3 3\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Không có phần tử nào chia hết (Mẫu 2)', 'input_data': '8 6\n-1 -2 1 -3 -1 4 -5 5\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Mọi phần tử đều chia hết', 'input_data': '5 3\n3 6 9 12 15\n', 'expected_output': '5\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Không phần tử nào chia hết', 'input_data': '4 5\n1 2 3 4\n', 'expected_output': '0\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Có số 0 (0 chia hết cho mọi k)', 'input_data': '6 10\n10 20 0 30 4 50\n', 'expected_output': '4\n'}]}, {'id': 'DRAGON-93', 'title': 'Phân Số Đơn Vị (1/x = 1/a + 1/b + 1/c)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào số nguyên dương $x$. Hãy tìm 3 số nguyên dương $a, b, c$ sao cho:\\n$$\\frac{1}{x} = \\frac{1}{a} + \\frac{1}{b} + \\frac{1}{c} \\quad (a \\le b \\le c)$$\\nÁp dụng hằng đẳng thức kinh điển phân tích phân số: $\\frac{1}{2} + \\frac{1}{3} + \\frac{1}{6} = 1 \\implies \\frac{1}{x} = \\frac{1}{2x} + \\frac{1}{3x} + \\frac{1}{6x}$.', 'input_format': 'Một dòng duy nhất ghi số nguyên dương $x$ ($1 \\le x \\le 10000$).', 'output_format': 'Ba số nguyên dương $a, b, c$ cách nhau một khoảng trắng ($a \\le b \\le c$).', 'constraints': '$1 \\le x \\le 10000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '5', 'sample_output': '10 15 30', 'hints': 'Sử dụng công thức tổng quát $a = 2x, b = 3x, c = 6x$. Ta luôn có $1/(2x) + 1/(3x) + 1/(6x) = 1/x$.', 'python_starter': "# Bí kíp luyện rồng - Phân Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phân Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    x = int(line)\n    print(f"{2 * x} {3 * x} {6 * x}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long x;\n    if (scanf("%lld", &x) == 1) {\n        printf("%lld %lld %lld\\n", 2 * x, 3 * x, 6 * x);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Với mọi số nguyên dương $x$, ta nhận thấy $1/2 + 1/3 + 1/6 = 3/6 + 2/6 + 1/6 = 6/6 = 1$. Khi chia cả hai vế cho $x$, ta thu được đẳng thức đẹp mắt:\\n$$\\frac{1}{x} = \\frac{1}{2x} + \\frac{1}{3x} + \\frac{1}{6x}$$\\nVới $a = 2x, b = 3x, c = 6x$, ba số này luôn là số nguyên dương và thỏa mãn $a \\le b \\le c$.\\n- **Độ phức tạp:** Thời gian $O(1)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu x = 5)', 'input_data': '5\n', 'expected_output': '10 15 30\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Biên dưới (x = 1)', 'input_data': '1\n', 'expected_output': '2 3 6\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test x = 2', 'input_data': '2\n', 'expected_output': '4 6 12\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test x = 10', 'input_data': '10\n', 'expected_output': '20 30 60\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Biên trên x = 10000', 'input_data': '10000\n', 'expected_output': '20000 30000 60000\n'}]}, {'id': 'DRAGON-94', 'title': 'Tam Giác Pascal', 'chapter': 'Phần IV. Mảng 2 chiều & Tổ hợp', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 94 trong Bí kíp luyện rồng:\n\nNhập vào một số nguyên dương $n$ ($1 \\le n \\le 10$). Hãy in ra tam giác Pascal bậc $n$.\n\nCác số trên mỗi dòng cách nhau đúng một dấu cách.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10$).', 'output_format': 'In ra $n$ dòng của tam giác Pascal.', 'constraints': '$1 \\le n \\le 10$.', 'sample_input': '5', 'sample_output': '1\n1 1\n1 2 1\n1 3 3 1\n1 4 6 4 1', 'hints': 'Dòng $i$ có $i$ phần tử: phần tử đầu và cuối luôn bằng 1, các phần tử ở giữa $C[i][j] = C[i-1][j-1] + C[i-1][j]$.', 'python_starter': "# Bí kíp luyện rồng - Bài 94: Tam Giác Pascal\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 94: Tam Giác Pascal\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    c = []\n    for i in range(n):\n        row = [1] * (i + 1)\n        for j in range(1, i):\n            row[j] = c[i-1][j-1] + c[i-1][j]\n        c.append(row)\n        print(" ".join(str(x) for x in row))\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int c[15][15];\n        for (int i = 0; i < n; i++) {\n            c[i][0] = 1;\n            c[i][i] = 1;\n            for (int j = 1; j < i; j++) {\n                c[i][j] = c[i-1][j-1] + c[i-1][j];\n            }\n            for (int j = 0; j <= i; j++) {\n                printf("%d%s", c[i][j], (j == i) ? "\\n" : " ");\n            }\n        }\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Sử dụng hệ thức tam giác Pascal:\n  $$C(n, k) = C(n-1, k-1) + C(n-1, k)$$\n- Khởi tạo $C[i][0] = 1$ và $C[i][i] = 1$.\n- Tính toán từng dòng và in ra cách nhau 1 dấu cách.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: n = 5)', 'input_data': '5\n', 'expected_output': '1\n1 1\n1 2 1\n1 3 3 1\n1 4 6 4 1\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (n = 3)', 'input_data': '3\n', 'expected_output': '1\n1 1\n1 2 1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên nhỏ nhất (n = 1)', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 2', 'input_data': '2\n', 'expected_output': '1\n1 1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10', 'input_data': '10\n', 'expected_output': '1\n1 1\n1 2 1\n1 3 3 1\n1 4 6 4 1\n1 5 10 10 5 1\n1 6 15 20 15 6 1\n1 7 21 35 35 21 7 1\n1 8 28 56 70 56 28 8 1\n1 9 36 84 126 126 84 36 9 1\n'}]}, {'id': 'DRAGON-95', 'title': 'Tổng Liên Tiếp (Phân Tích Thành Tổng)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào số nguyên dương $n$. Hãy tìm cách phân tích $n$ thành tổng các số nguyên dương liên tiếp (ít nhất 2 số). Dữ liệu đảm bảo luôn có thể phân tích được. Nếu có nhiều cách phân tích, chọn cách có nhiều số hạng nhất (bắt đầu từ số nhỏ nhất).', 'input_format': 'Một dòng ghi số nguyên dương $n$ ($1 \\le n \\le 1000000$).', 'output_format': 'In ra các số nguyên dương liên tiếp có tổng bằng $n$, các số từ bé đến lớn cách nhau 1 dấu cách.', 'constraints': '$1 \\le n \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '10', 'sample_output': '1 2 3 4', 'hints': 'Nếu tổng có $k$ số bắt đầu từ $s$, ta có công thức: $k \\times s + k(k-1)/2 = n$. Duyệt $k$ từ giá trị lớn nhất giảm dần về 2.', 'python_starter': "# Bí kíp luyện rồng - Tổng Liên Tiếp\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Tổng Liên Tiếp\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    max_k = int(math.isqrt(2 * n)) + 2\n    for k in range(max_k, 1, -1):\n        rem = n - k * (k - 1) // 2\n        if rem > 0 and rem % k == 0:\n            s = rem // k\n            res = [str(s + i) for i in range(k)]\n            print(" ".join(res))\n            return\n    print(n)\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long max_k = (long long)sqrt(2 * n) + 2;\n        for (long long k = max_k; k >= 2; k--) {\n            long long rem = n - k * (k - 1) / 2;\n            if (rem > 0 && rem % k == 0) {\n                long long s = rem / k;\n                for (long long i = 0; i < k; i++) {\n                    printf("%lld%c", s + i, (i == k - 1) ? \'\\n\' : \' \');\n                }\n                return 0;\n            }\n        }\n        printf("%lld\\n", n);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Giả sử $n$ được biểu diễn thành tổng của $k$ số nguyên dương liên tiếp bắt đầu từ $s$: $n = s + (s+1) + \\dots + (s+k-1) = k \\cdot s + \\frac{k(k-1)}{2}$.\\n- Ta suy ra: $k \\cdot s = n - \\frac{k(k-1)}{2}$. Để tìm cách phân tích có nhiều số hạng nhất, ta cho $k$ giảm dần từ $\\sqrt{2n}$ về $2$. Giá trị $k$ đầu tiên thỏa mãn $n - k(k-1)/2 > 0$ và chia hết cho $k$ sẽ cho dãy dài nhất.\\n- **Độ phức tạp:** Thời gian $O(\\sqrt{n})$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 10 -> 1 2 3 4)', 'input_data': '10\n', 'expected_output': '1 2 3 4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test n = 15 (1 2 3 4 5)', 'input_data': '15\n', 'expected_output': '1 2 3 4 5\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test n = 3 (1 2)', 'input_data': '3\n', 'expected_output': '1 2\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 21 (1 2 3 4 5 6)', 'input_data': '21\n', 'expected_output': '1 2 3 4 5 6\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Test n = 100 (9 10 11 12 13 14 15 16)', 'input_data': '100\n', 'expected_output': '9 10 11 12 13 14 15 16\n'}]}, {'id': 'DRAGON-96', 'title': 'Phần Tử Yên Ngựa (Saddle Point)', 'chapter': 'Phần IX. Mảng hai chiều & Ma trận', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào ma trận $A$ kích thước $n \\times m$. In ra số lượng các phần tử yên ngựa trong ma trận.\\nMột phần tử $a[i, j]$ được coi là phần tử yên ngựa khi nó đồng thời là phần tử nhỏ nhất của hàng $i$ và là phần tử lớn nhất của cột $j$.', 'input_format': 'Dòng 1: Hai số nguyên dương $n, m$ ($1 \\le n, m \\le 20$).\\n$n$ dòng tiếp theo, mỗi dòng là $m$ số nguyên trong khoảng $[-1000, 1000]$.', 'output_format': 'In ra số lượng phần tử yên ngựa tìm được.', 'constraints': '$1 \\le n, m \\le 20$\\n$-1000 \\le a[i, j] \\le 1000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '3 4\n4 4 4 5\n5 6 4 8\n5 8 5 7', 'sample_output': '2', 'hints': 'Tính trước mảng giá trị nhỏ nhất của mỗi hàng `row_min[i]` và giá trị lớn nhất của mỗi cột `col_max[j]`. Sau đó đếm các vị trí $(i, j)$ có $a[i][j] == row\\_min[i] == col\\_max[j]$.', 'python_starter': "# Bí kíp luyện rồng - Phần Tử Yên Ngựa\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phần Tử Yên Ngựa\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n, m = int(tokens[0]), int(tokens[1])\n    idx = 2\n    matrix = []\n    for _ in range(n):\n        matrix.append([int(x) for x in tokens[idx:idx+m]])\n        idx += m\n    row_mins = [min(row) for row in matrix]\n    col_maxs = [max(matrix[r][c] for r in range(n)) for c in range(m)]\n    count = 0\n    for r in range(n):\n        for c in range(m):\n            if matrix[r][c] == row_mins[r] and matrix[r][c] == col_maxs[c]:\n                count += 1\n    print(count)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n, m;\n    if (scanf("%d %d", &n, &m) == 2) {\n        int a[25][25];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n                scanf("%d", &a[i][j]);\n            }\n        }\n        int row_min[25], col_max[25];\n        for (int i = 0; i < n; i++) {\n            row_min[i] = a[i][0];\n            for (int j = 1; j < m; j++) {\n                if (a[i][j] < row_min[i]) row_min[i] = a[i][j];\n            }\n        }\n        for (int j = 0; j < m; j++) {\n            col_max[j] = a[0][j];\n            for (int i = 1; i < n; i++) {\n                if (a[i][j] > col_max[j]) col_max[j] = a[i][j];\n            }\n        }\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n                if (a[i][j] == row_min[i] && a[i][j] == col_max[j]) {\n                    count++;\n                }\n            }\n        }\n        printf("%d\\n", count);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Đầu tiên, tính trước giá trị nhỏ nhất của mỗi hàng lưu vào mảng `row_min[i]` và giá trị lớn nhất của mỗi cột lưu vào `col_max[j]`. Sau đó, duyệt lại toàn bộ ma trận: phần tử tại $(i, j)$ là điểm yên ngựa nếu $a[i][j] == row\\_min[i]$ và $a[i][j] == col\\_max[j]$.\\n- **Độ phức tạp:** Thời gian $O(n \\times m)$, Bộ nhớ $O(n + m)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 3x4)', 'input_data': '3 4\n4 4 4 5\n5 6 4 8\n5 8 5 7\n', 'expected_output': '2\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Ma trận 1x1 (luôn là yên ngựa)', 'input_data': '1 1\n42\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Ma trận không có yên ngựa', 'input_data': '2 2\n1 2\n4 3\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Ma trận toàn phần tử bằng nhau', 'input_data': '3 3\n5 5 5\n5 5 5\n5 5 5\n', 'expected_output': '9\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Ma trận đường chéo', 'input_data': '3 3\n9 2 3\n4 8 6\n7 5 1\n', 'expected_output': '0\n'}]}, {'id': 'DRAGON-97', 'title': 'Gạch Số Tạo Số Lớn Nhất', 'chapter': 'Phần V. Xâu ký tự & Thuật toán tham lam (Greedy)', 'difficulty': 'Khó', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 97 trong Bí kíp luyện rồng:\n\nCho xâu ký tự số $S$ và số nguyên dương $k$ ($k < |S|$). Hãy gạch bỏ đúng $k$ chữ số từ $S$ sao cho số còn lại tạo thành là lớn nhất có thể (giữ nguyên thứ tự các chữ số còn lại).\n\nIn ra xâu ký tự số lớn nhất sau khi gạch bỏ.', 'input_format': 'Dòng 1 ghi số nguyên dương $k$ (nhỏ hơn độ dài của xâu). Dòng 2 ghi xâu $S$ gồm các ký tự số (độ dài không quá 100).', 'output_format': 'In ra xâu $S$ sau khi xoá.', 'constraints': '$1 \\le k < |S| \\le 100$.', 'sample_input': '3\n23571113', 'sample_output': '71113', 'hints': 'Dùng cấu trúc dữ liệu Ngăn xếp (Stack) hoặc thuật toán Tham lam (Monotonic Stack). Mỗi khi chữ số hiện tại lớn hơn chữ số đỉnh stack và ta vẫn còn quyền xoá (k > 0), xoá phần tử đỉnh stack.', 'python_starter': "# Bí kíp luyện rồng - Bài 97: Gạch Số #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 97: Gạch Số #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        k = int(parts[0])\n        s = parts[1]\n        stack = []\n        to_remove = k\n        for digit in s:\n            while stack and to_remove > 0 and stack[-1] < digit:\n                stack.pop()\n                to_remove -= 1\n            stack.append(digit)\n        while to_remove > 0 and stack:\n            stack.pop()\n            to_remove -= 1\n        print("".join(stack))\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    int k;\n    char s[200];\n    if (scanf("%d %s", &k, s) == 2) {\n        char stack[200];\n        int top = 0;\n        int to_remove = k;\n        int len = strlen(s);\n        for (int i = 0; i < len; i++) {\n            while (top > 0 && to_remove > 0 && stack[top - 1] < s[i]) {\n                top--;\n                to_remove--;\n            }\n            stack[top++] = s[i];\n        }\n        while (to_remove > 0 && top > 0) {\n            top--;\n            to_remove--;\n        }\n        stack[top] = \'\\0\';\n        printf("%s\\n", stack);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Sử dụng thuật toán Ngăn xếp đơn điệu (Monotonic Stack):\n  - Để số tạo thành là lớn nhất, các chữ số có giá trị lớn hơn phải ưu tiên nằm ở hàng cao hơn (bên trái).\n  - Khi duyệt từng chữ số $c$ của $S$: chừng nào ngăn xếp còn phần tử, còn lượt xoá $k > 0$ và phần tử đỉnh stack $< c$, ta loại bỏ đỉnh stack.\n  - Sau khi duyệt hết, nếu vẫn còn $k > 0$, loại bỏ tiếp $k$ phần tử từ cuối stack.\n- Độ phức tạp thời gian: $O(|S|)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu sách: k=3, 23571113 -> 71113)', 'input_data': '3\n23571113\n', 'expected_output': '71113\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (k=1, 1432 -> 432)', 'input_data': '1\n1432\n', 'expected_output': '432\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test dãy giảm dần (9876, k=2 -> 98)', 'input_data': '2\n9876\n', 'expected_output': '98\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test dãy tăng dần (12345, k=2 -> 345)', 'input_data': '2\n12345\n', 'expected_output': '345\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test chuỗi dài', 'input_data': '5\n918273645\n', 'expected_output': '9876\n'}]}, {'id': 'DRAGON-98', 'title': 'Gạch Số #2 (Tạo Số Nhỏ Nhất)', 'chapter': 'Phần X. Kỹ thuật nâng cao & Thuật toán', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Cho xâu ký tự số $S$. Hãy gạch đi $k$ chữ số bất kỳ sao cho các chữ số còn lại theo thứ tự ban đầu tạo thành số có giá trị nhỏ nhất có thể.', 'input_format': "Dòng 1: Số nguyên dương $k$ (nhỏ hơn độ dài của xâu $S$).\\nDòng 2: Xâu $S$ gồm các ký tự chữ số từ '0' đến '9' (độ dài không quá 100).", 'output_format': 'In ra xâu $S$ sau khi xoá $k$ chữ số.', 'constraints': '$1 \\le k < |S| \\le 100$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '3\n23571113', 'sample_output': '21113', 'hints': 'Sử dụng cấu trúc ngăn xếp (Monotonic Stack): khi duyệt chữ số mới nhỏ hơn đỉnh ngăn xếp và còn lượt xóa $k$, ta pop đỉnh ngăn xếp ra.', 'python_starter': "# Bí kíp luyện rồng - Gạch Số #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Gạch Số #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    k = int(tokens[0])\n    s = tokens[1]\n    stack = []\n    k_left = k\n    for ch in s:\n        while stack and stack[-1] > ch and k_left > 0:\n            stack.pop()\n            k_left -= 1\n        stack.append(ch)\n    if k_left > 0:\n        stack = stack[:-k_left]\n    print("".join(stack))\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    int k;\n    char s[205];\n    if (scanf("%d %s", &k, s) == 2) {\n        char stack[205];\n        int top = 0;\n        int k_left = k;\n        int len = strlen(s);\n        for (int i = 0; i < len; i++) {\n            while (top > 0 && stack[top - 1] > s[i] && k_left > 0) {\n                top--;\n                k_left--;\n            }\n            stack[top++] = s[i];\n        }\n        top -= k_left;\n        stack[top] = \'\\0\';\n        printf("%s\\n", stack);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Để số tạo thành là nhỏ nhất, các chữ số ở hàng cao hơn phải càng nhỏ càng tốt. Ta dùng kỹ thuật Monotonic Stack tăng dần: duyệt từng ký tự chữ số của $S$, nếu chữ số đỉnh stack lớn hơn chữ số hiện tại và vẫn còn lượt xóa ($k > 0$), ta loại bỏ đỉnh stack.\\n- Nếu sau khi duyệt hết chuỗi mà vẫn còn lượt xóa $k$, ta cắt bỏ $k$ ký tự cuối cùng của stack.\\n- **Độ phức tạp:** Thời gian $O(|S|)$, Bộ nhớ $O(|S|)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '3\n23571113\n', 'expected_output': '21113\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Dãy giảm dần xoá hết số lớn', 'input_data': '3\n987654\n', 'expected_output': '654\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Dãy tăng dần xoá ở đuôi', 'input_data': '2\n12345\n', 'expected_output': '123\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Có số 0 ở giữa', 'input_data': '2\n10200\n', 'expected_output': '0200\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Chuỗi dài xoá nhiều số', 'input_data': '4\n43214321\n', 'expected_output': '121\n'}]}, {'id': 'DRAGON-99', 'title': 'Sắp Xếp Xoắn Ốc (Spiral Sort)', 'chapter': 'Phần IX. Mảng hai chiều & Ma trận', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Cho mảng hai chiều $A$ kích thước $n \\times m$. Hãy sắp xếp tất cả các phần tử trong mảng $A$ theo thứ tự tăng dần theo chiều kim đồng hồ (xoắn ốc từ ngoài vào trong).', 'input_format': 'Dòng 1: Hai số nguyên dương $n, m$ ($1 \\le n, m \\le 20$).\\n$n$ dòng tiếp theo, mỗi dòng ghi $m$ số nguyên trong khoảng $[-1000, 1000]$.', 'output_format': 'In ra mảng $A$ sau khi sắp xếp xoắn ốc (gồm $n$ dòng, mỗi dòng $m$ số cách nhau bởi một khoảng trắng).', 'constraints': '$1 \\le n, m \\le 20$\\n$-1000 \\le a[i, j] \\le 1000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '4 4\n4 5 7 1\n21 32 10 6\n3 2 9 11\n13 20 34 67', 'sample_output': '1 2 3 4\n20 21 32 5\n13 67 34 6\n11 10 9 7', 'hints': 'Thu thập tất cả $n \\times m$ phần tử vào một mảng 1D rồi sắp xếp tăng dần. Sau đó điền tuần tự các phần tử vào ma trận theo 4 đường biên (trên, phải, dưới, trái).', 'python_starter': "# Bí kíp luyện rồng - Sắp Xếp Xoắn Ốc\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Sắp Xếp Xoắn Ốc\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n, m = int(tokens[0]), int(tokens[1])\n    vals = sorted([int(x) for x in tokens[2:2 + n * m]])\n    res = [[0] * m for _ in range(n)]\n    top, bottom, left, right = 0, n - 1, 0, m - 1\n    idx = 0\n    while top <= bottom and left <= right:\n        for c in range(left, right + 1):\n            res[top][c] = vals[idx]\n            idx += 1\n        top += 1\n        for r in range(top, bottom + 1):\n            res[r][right] = vals[idx]\n            idx += 1\n        right -= 1\n        if top <= bottom:\n            for c in range(right, left - 1, -1):\n                res[bottom][c] = vals[idx]\n                idx += 1\n            bottom -= 1\n        if left <= right:\n            for r in range(bottom, top - 1, -1):\n                res[r][left] = vals[idx]\n                idx += 1\n            left += 1\n    for row in res:\n        print(" ".join(map(str, row)))\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int*)a - *(int*)b);\n}\n\nint main() {\n    int n, m;\n    if (scanf("%d %d", &n, &m) == 2) {\n        int total = n * m;\n        int *vals = (int*)malloc(total * sizeof(int));\n        for (int i = 0; i < total; i++) {\n            scanf("%d", &vals[i]);\n        }\n        qsort(vals, total, sizeof(int), cmp);\n        int res[25][25];\n        int top = 0, bottom = n - 1, left = 0, right = m - 1;\n        int idx = 0;\n        while (top <= bottom && left <= right) {\n            for (int c = left; c <= right; c++) res[top][c] = vals[idx++];\n            top++;\n            for (int r = top; r <= bottom; r++) res[r][right] = vals[idx++];\n            right--;\n            if (top <= bottom) {\n                for (int c = right; c >= left; c--) res[bottom][c] = vals[idx++];\n                bottom--;\n            }\n            if (left <= right) {\n                for (int r = bottom; r >= top; r--) res[r][left] = vals[idx++];\n                left++;\n            }\n        }\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n                printf("%d%c", res[i][j], (j == m - 1) ? \'\\n\' : \' \');\n            }\n        }\n        free(vals);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Đọc toàn bộ $n \\times m$ phần tử vào mảng và sắp xếp tăng dần. Ta dùng 4 con trỏ giới hạn vùng ma trận chưa điền: `top = 0, bottom = n - 1, left = 0, right = m - 1`. Lần lượt điền theo 4 hướng kim đồng hồ: từ trái sang phải ở hàng `top`, từ trên xuống dưới ở cột `right`, từ phải sang trái ở hàng `bottom`, và từ dưới lên trên ở cột `left`.\\n- **Độ phức tạp:** Thời gian $O((n m) \\log(n m))$, Bộ nhớ $O(n m)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 4x4)', 'input_data': '4 4\n4 5 7 1\n21 32 10 6\n3 2 9 11\n13 20 34 67\n', 'expected_output': '1 2 3 4\n20 21 32 5\n13 67 34 6\n11 10 9 7\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Ma trận 1x1', 'input_data': '1 1\n99\n', 'expected_output': '99\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Ma trận 2x2', 'input_data': '2 2\n4 2\n1 3\n', 'expected_output': '1 2\n4 3\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Ma trận 1 hàng 3 cột', 'input_data': '1 3\n3 1 2\n', 'expected_output': '1 2 3\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Ma trận 3 hàng 1 cột', 'input_data': '3 1\n8\n2\n5\n', 'expected_output': '2\n5\n8\n'}]}, {'id': 'DRAGON-100', 'title': 'Chia Mảng Tỉ Lệ 1:K', 'chapter': 'Phần IV. Mảng một chiều & Kỹ thuật cộng dồn', 'difficulty': 'Khó', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 100 trong Bí kíp luyện rồng:\n\nCho mảng $A$ gồm $n$ phần tử dương ($n > 1$). Hãy tìm cách chia mảng $A$ thành 2 đoạn con liên tiếp sao cho tổng các phần tử của một đoạn gấp $k$ lần tổng các phần tử của đoạn còn lại ($S_1 = k \\times S_2$ hoặc $S_2 = k \\times S_1$).\n\nIn ra hai số nguyên dương là số lượng phần tử của đoạn trước và đoạn sau (cách nhau một dấu cách). Trong trường hợp không chia được theo tỉ lệ trên, in ra `NO`.', 'input_format': 'Dòng 1 ghi hai số nguyên dương $n, k$ ($2 \\le n \\le 1000, 1 \\le k \\le 100$). Dòng tiếp theo ghi $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 10^6$).', 'output_format': 'In ra 2 số nguyên là số phần tử của 2 đoạn (cách nhau 1 khoảng trắng). Nếu không được, in `NO`.', 'constraints': '$2 \\le n \\le 1000, 1 \\le k \\le 100$; $1 \\le a_i \\le 10^6$.', 'sample_input': '8 3\n2 3 1 2 3 3 4 2', 'sample_output': '2 6', 'hints': 'Tính tổng mảng $S$. Kiểm tra điểm cắt $i$ ($1 \\le i < n$). Gọi $S_1$ là tổng $i$ phần tử đầu, $S_2 = S - S_1$. Nếu $S_2 == k \\times S_1$ hoặc $S_1 == k \\times S_2$, in ra $i$ và $n - i$.', 'python_starter': "# Bí kíp luyện rồng - Bài 100: Chia Mảng Tỉ Lệ 1:K\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 100: Chia Mảng Tỉ Lệ 1:K\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) < 2:\n        return\n    n = int(parts[0])\n    k = int(parts[1])\n    a = [int(x) for x in parts[2:2+n]]\n    total_sum = sum(a)\n    prefix_sum = 0\n    for i in range(n - 1):\n        prefix_sum += a[i]\n        suffix_sum = total_sum - prefix_sum\n        if prefix_sum * k == suffix_sum or suffix_sum * k == prefix_sum:\n            print(f"{i + 1} {n - (i + 1)}")\n            return\n    print("NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    long long k;\n    if (scanf("%d %lld", &n, &k) == 2) {\n        long long a[1005];\n        long long total = 0;\n        for (int i = 0; i < n; i++) {\n            scanf("%lld", &a[i]);\n            total += a[i];\n        }\n        long long prefix = 0;\n        for (int i = 0; i < n - 1; i++) {\n            prefix += a[i];\n            long long suffix = total - prefix;\n            if (prefix * k == suffix || suffix * k == prefix) {\n                printf("%d %d\\n", i + 1, n - (i + 1));\n                return 0;\n            }\n        }\n        printf("NO\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Gọi tổng toàn bộ mảng là $S$.\n- Duyệt vị trí cắt $i$ từ $0$ đến $n-2$:\n  - Tổng đoạn đầu $S_1 = \\sum_{j=0}^i a_j$.\n  - Tổng đoạn sau $S_2 = S - S_1$.\n  - Kiểm tra nếu $S_1 \\times k == S_2$ hoặc $S_2 \\times k == S_1$, ta dừng lại và in ra độ dài đoạn trước là $i+1$ và đoạn sau là $n - (i+1)$.\n- Nếu duyệt hết mà không thỏa mãn, in `NO`.\n- Độ phức tạp thời gian: $O(N)$ bằng kỹ thuật tổng tiền tố (prefix sum).', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu sách: S2 = 3 * S1 -> 2 6)', 'input_data': '8 3\n2 3 1 2 3 3 4 2\n', 'expected_output': '2 6\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Không thể chia -> NO)', 'input_data': '8 3\n2 3 1 2 3 3 4 3\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test đoạn trước gấp k lần đoạn sau', 'input_data': '4 2\n6 6 4 2\n', 'expected_output': '1 3\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test tỉ lệ 1:1 (k = 1)', 'input_data': '4 1\n1 2 2 1\n', 'expected_output': '2 2\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test mảng lớn', 'input_data': '5 4\n1 1 1 1 16\n', 'expected_output': '4 1\n'}]}]
